 for(const c of ws.cases||[]){c.aiClassification=c.aiClassification||'non_valutata';c.aiClassReason=c.aiClassReason||'';c.aiClassBy=c.aiClassBy||'';c.aiClassAt=c.aiClassAt||null;c.friaDecision=c.friaDecision||'non_valutata';c.friaReason=c.friaReason||'';c.friaBy=c.friaBy||'';c.friaAt=c.friaAt||null;c.oversightOwner=c.oversightOwner||'';c.oversightMethod=c.oversightMethod||'';c.oversightAuthority=c.oversightAuthority||'';c.oversightEvidence=c.oversightEvidence||'';c.riskValidation=c.riskValidation||'';c.riskValidationReason=c.riskValidationReason||'';c.riskValidatedBy=c.riskValidatedBy||'';c.riskValidatedAt=c.riskValidatedAt||null;c.riskHistory=Array.isArray(c.riskHistory)?c.riskHistory:[];c.processorName=c.processorName||'';c.processorActRef=c.processorActRef||'';c.processorActDate=c.processorActDate||'';c.processorScope=c.processorScope||'';c.residualRiskAccepted=Boolean(c.residualRiskAccepted);c.residualRiskAcceptedBy=c.residualRiskAcceptedBy||'';c.residualRiskAcceptedAt=c.residualRiskAcceptedAt||null;c.residualRiskAcceptanceNote=c.residualRiskAcceptanceNote||''}
 for(const t of ws.tasks||[]){t.validatedAt=t.validatedAt||null;t.validatedBy=t.validatedBy||'';t.completedBy=t.completedBy||'';if(t.status==='completed'&&!taskReadiness(ws,t).ok){t.status='open';t.completedAt=null;t.completedBy='';t.validatedAt=null;t.validatedBy='';t.migrationNote='v2.0: riaperto perché mancavano evidenze validate o documenti approvati'}if(!['completed','non_applicabile'].includes(t.status))refreshTaskStatus(ws,t)}
