// Snapshot read-only: no assessment or administrative state is modified.
function dossierSnapshot(ws,c,today=new Date().toISOString().slice(0,10)){
 const tasks=ws.tasks.filter(t=>t.caseId===c.id&&t.status!=='non_applicabile');
 const docs=ws.documents.filter(d=>d.caseId===c.id);
 const evidence=ws.evidence.filter(e=>e.caseId===c.id);
 const specialists=specialistContributions(c),presc=prescriptions(c),monitor=prescriptionMonitoring(c,today);
 const individual=individualRiskSummary(ws,c),readiness=authorizationReadiness(ws,c);
 const decisions=(ws.decisions||[]).filter(x=>x.caseId===c.id);
 const timeline=(ws.events||[]).filter(x=>x.caseId===c.id).slice().sort((a,b)=>String(b.at||b.createdAt||'').localeCompare(String(a.at||a.createdAt||'')));
 const assessments=assessmentCompletion(c);
 const completed=tasks.filter(t=>t.status==='completed').length;
 const required=specialists.filter(x=>x.required),pending=required.filter(x=>x.status!=='received');
 const openPre=presc.filter(x=>x.phase==='pre'&&x.status!=='verified');
 const status=c.denial?.active?'Diniego attivo':c.authorized?(monitor.open.length?'Autorizzato con prescrizioni aperte':'Autorizzato'):'In istruttoria';
 return {caseId:c.id,name:c.name,purpose:c.purpose||'',owner:c.owner||'',area:c.area||'',vendor:c.vendor||'',status,
 assessment:{percent:assessments.pct,complete:assessments.complete,methodVersion:Assessment4.VERSION,answers:clone(c.answers),analysis:Assessment4.analyse(c)},
 tasks:{total:tasks.length,completed,open:tasks.length-completed},
 evidence:{total:evidence.length,validated:evidence.filter(e=>e.status==='validated'||e.validatedAt).length},
 documents:{total:docs.length,approved:docs.filter(d=>d.status==='approved'&&!d.stale).length,items:docs.map(d=>({type:d.type,status:d.status,stale:!!d.stale,updatedAt:d.updatedAt||d.createdAt||''}))},
 regionalPolicy:clone(c.regionalPolicy||null),regionalVersion:Regional.VERSION,reuseProfile:clone(c.reuseProfile||{}),acceptanceCriteria:clone(c.acceptanceCriteria||[]),safetyPlan:clone(c.safetyPlan||null),
 risks:{projected:riskMatrixData(ws,c).projected,method:riskMatrixData(ws,c).method,total:individual.total,validated:individual.validated,pending:individual.pending.length,automatic:riskMatrixData(ws,c).after,final:readiness.measuresReady&&readiness.individualRisksValidated&&readiness.riskValidated?c.riskValidation:null,validatedBy:c.riskValidatedBy||''},
 specialists:{total:specialists.length,required:required.length,pending:pending.length,items:specialists.map(x=>({role:x.role,subject:x.subject,status:x.status,outcome:x.outcome||'',required:x.required}))},
 prescriptions:{total:presc.length,preventiveOpen:openPre.length,inExerciseOpen:monitor.open.length,overdue:monitor.overdue.length,items:presc.map(x=>({title:x.title,owner:x.owner,phase:x.phase,status:x.status,dueDate:x.dueDate||'',overdue:monitor.overdue.some(y=>y.id===x.id)}))},
 decision:{authorized:!!c.authorized,denied:!!c.denial?.active,history:decisions.map(x=>({type:x.type,outcome:x.outcome,author:x.author,at:x.at,basis:x.basis||''}))},
 readiness:{ready:readiness.ready,missing:readiness.missing.slice()},nextReviewAt:c.nextReviewAt||'',timeline:timeline.map(x=>({type:x.type,at:x.at||x.createdAt||'',payload:x.payload||{}}))};
}

